SELECT toString(properties.operation) AS Operation,uniqExact(person_id) AS People,uniqExactIf(properties.operation_id,event='native_operation_started') AS Started,uniqExactIf(properties.operation_id,event='native_operation_finished') AS Finished,round(quantileIf(0.95)(toFloat(properties.elapsed_seconds),event='native_operation_finished'),1) AS p95_seconds FROM events WHERE event IN ('native_operation_started','native_operation_finished') AND properties.environment = 'production' AND properties.product = 'studio' AND {filters} GROUP BY Operation ORDER BY Started DESC LIMIT 30
